// Task представляет собой задачу, которую нужно обработать.
type Task struct {
	ID   int
	Data string
}

// WorkerPool — пул воркеров, обрабатывающих задачи из канала с ограничением параллелизма.
// Пул использует фиксированное количество горутины-воркеров, которые одновременно
// выполняют задачи. Задачи поступают в канал и распределяются между свободными воркерами.
type WorkerPool struct {
	// taskCh — канал для передачи задач от отправителя к воркерам.
	taskCh chan Task

	// wg — WaitGroup для ожидания завершения всех воркеров.
	wg sync.WaitGroup

	// numWorkers — количество воркеров в пуле.
	numWorkers int

	// ctx — контекст для управления жизненным циклом пула.
	ctx context.Context

	// cancel — функция отмены контекста.
	cancel context.CancelFunc
}

// NewWorkerPool создаёт новый экземпляр WorkerPool.
// Параметры:
//   - numWorkers: количество воркеров, которые будут работать одновременно.
//     Должно быть положительным числом.
// Возвращает указатель на созданный пул.
func NewWorkerPool(numWorkers int) *WorkerPool {
	if numWorkers <= 0 {
		panic("количество воркеров должно быть положительным")
	}

	// Создаём контекст с возможностью отмены.
	ctx, cancel := context.WithCancel(context.Background())

	return &WorkerPool{
		taskCh:     make(chan Task), // Канал без буфера: задача передаётся только когда воркер готов её принять.
		wg:         sync.WaitGroup{},
		numWorkers: numWorkers,
		ctx:        ctx,
		cancel:     cancel,
	}
}

// Start запускает все воркеры пула.
// Каждый воркер начинает слушать канал taskCh и обрабатывать поступающие задачи.
// Метод не блокируется — воркеры работают в отдельных горутинах.
func (wp *WorkerPool) Start() {
	for i := 0; i < wp.numWorkers; i++ {
		wp.wg.Add(1) // Увеличиваем счётчик WaitGroup, чтобы знать, сколько воркеров ещё активно.
		go wp.worker(i)
	}
