    // Проверяем, что процент скидки находится в допустимом диапазоне от 0 до 100
    if (percent < 0 || percent > 100) throw new IllegalArgumentException("percent");

    // Вычисляем коэффициент умножения: (100 - percent) / 100
    // Например, при скидке 20% коэффициент будет 80/100 = 0.8
    BigDecimal k = BigDecimal.valueOf(100 - percent).divide(BigDecimal.valueOf(100));

    // Умножаем исходную цену на коэффициент и округляем результат до 2 знаков после запятой
    // Используем RoundingMode.HALF_EVEN (округление "в четную сторону") для точности финансовых расчетов
    return price.multiply(k).setScale(2, RoundingMode.HALF_EVEN);
}
```

