// Метод Get извлекает значение по ключу из кэша.
// Возвращает пару: (значение, найдено ли оно и не истекло ли время жизни).
func (c *Cache) Get(key string) (string, bool) {
    // Блокируем чтение данных в кэше, чтобы обеспечить безопасный доступ
    // к общей структуре данных при одновременном чтении несколькими горутинами.
    c.mu.RLock()

    // Пытаемся получить элемент из карты по указанному ключу.
    // ok будет true, если ключ найден, иначе false.
    e, ok := c.items[key]

    // Разблокируем чтение, так как данные уже получены.
    c.mu.RUnlock()

    // Проверяем, был ли элемент найден (ok == true) и не истекло ли его время жизни.
    // Если элемент не найден или срок действия истек — возвращаем пустую строку и false.
    if !ok || time.Now().After(e.expires) {
        return "", false
    }

    // Если элемент найден и актуален — возвращаем его значение и true.
    return e.value, true
}
