/**
 * Создаёт функцию-обёртку, которая откладывает вызов переданной функции на указанное время.
 * Если функция вызывается повторно до истечения таймера, предыдущий таймер сбрасывается,
 * и отсчёт времени начинается заново. Это позволяет "гасить" частые вызовы (например, при вводе текста)
 * и выполнять действие только после паузы.
 *
 * @param fn - Функция, которую нужно обернуть в debounce.
 * @param ms - Задержка в миллисекундах, по прошествии которой будет выполнен вызов `fn`.
 * @returns Обёрнутая функция с теми же параметрами, что и исходная `fn`.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора текущего таймера.
  // Изначально она не определена, так как таймер ещё не создан.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная `fn`.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (т.е., функция была вызвана ранее и таймер ещё не истёк),
    // очищаем его, чтобы отменить предыдущий запланированный вызов.
    if (timer) clearTimeout(timer);

    // Создаём новый таймер, который через `ms` миллисекунд вызовет оригинальную функцию `fn`
    // с переданными аргументами `args`.
    // Сохраняем идентификатор нового таймера в переменную `timer`,
    // чтобы иметь возможность отменить его при следующем вызове.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

