/**
 * Функция для повторного выполнения блока кода при возникновении IOException.
 *
 * @param times Количество попыток выполнения блока.
 * @param block Блок кода, который нужно выполнить.
 * @return Результат выполнения блока, если он завершился успешно.
 * @throws IOException Если все попытки завершились с ошибкой IOException.
 * @throws IllegalStateException Если количество попыт (times) меньше или равно 0.
 */
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последней возникшей ошибки IOException
    var last: Throwable? = null

    // Цикл, выполняющий блок `block` не более `times` раз
    repeat(times) {
        try {
            // Пытаемся выполнить блок кода и вернуть его результат
            return block()
        } catch (e: IOException) {
            // Если произошла ошибка IOException, сохраняем её в переменную `last`
            // и продолжаем цикл (делаем следующую попытку)
            last = e
        }
    }

    // Если все попытки завершились с ошибкой, бросаем последнюю сохранённую ошибку
    // Если ошибок не было (например, times <= 0), бросаем IllegalStateException
    throw last ?: IllegalStateException("times must be > 0")
}
```

