/// Вычисляет медиану вектора чисел с плавающей точкой.
///
/// # Аргументы
/// * `v` - ссылка на изменяемый вектор, который будет отсортирован для вычисления медианы.
///
/// # Возвращаемое значение
/// * `Some(f64)` - если вектор не пустой, возвращает медиану.
/// * `None` - если вектор пустой.
pub fn median(v: &mut Vec<f64>) -> Option<f64> {
    // Если вектор пустой, медиана не определена, поэтому возвращаем None
    if v.is_empty() { return None; }

    // Сортируем вектор по возрастанию значений.
    // Используем partial_cmp, так как f64 может содержать NaN, и сравниваем только валидные значения.
    // unwrap() здесь безопасен, так как мы предполагаем, что все элементы — валидные числа (не NaN).
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());

    // Определяем индекс среднего элемента (для нечетной длины) или правого из двух средних (для четной длины)
    let m = v.len() / 2;

    // Возвращаем Some со значением медианы:
    // - Если длина вектора четная, берем среднее арифметическое двух центральных элементов (m-1 и m)
    // - Если длина нечетная, берем элемент с индексом m (центральный элемент)
    Some(if v.len() % 2 == 0 { 
        (v[m - 1] + v[m]) / 2.0 
    } else { 
        v[m] 
    })
}
