// Get возвращает значение из кэша по указанному ключу, если оно существует и не истекло время жизни (TTL).
//
// Функция является потокобезопасной: она использует read-lock для доступа к внутреннему состоянию кэша.
// Если ключ не найден или значение устарело (текущее время позже времени истечения), функция возвращает пустую строку и false.
//
// Параметры:
//   - key: строковый ключ, по которому выполняется поиск в кэше.
//
// Возвращаемые значения:
//   - string: значение из кэша, если оно найдено и актуально; иначе пустая строка.
//   - bool: true, если значение успешно получено; false, если ключ отсутствует или значение устарело.
//
// Граничные случаи:
//   - Пустой ключ: поведение зависит от реализации хранилища c.items. Обычно пустой ключ может быть допустимым, но рекомендуется проверять его перед вызовом.
//   - Устаревшее значение: если time.Now() > e.expires, значение считается недействительным и возвращается как отсутствующее.
//   - Отсутствие ключа: если ключ не найден в c.items, возвращается ("", false).
//
// Примечание:
//   - Функция не изменяет состояние кэша (не удаляет устаревшие записи при чтении).
//   - Для удаления устаревших записей следует использовать отдельную функцию очистки (например, Purge или GC).
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
```

