    {
        // Получаем культуру ru-RU и используем её стандартный формат короткой даты ("d")
        var culture = CultureInfo.GetCultureInfo("ru-RU");
        return date.ToString("d", culture);
    }
}
```

### Вариант 3: Если нужно именно жёстко зафиксировать формат строкой

