import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.jdbc.Sql;
import org.springframework.transaction.annotation.Transactional;

import static org.junit.jupiter.api.Assertions.assertEquals;

@Transactional // <— Добавляем аннотацию @Transactional
class AccountServiceTest {

    @Autowired
    private AccountService service;

    @Autowired
    private AccountRepository accounts; // Предполагаю, что у вас есть репозиторий

    @Test
    void savesInTransaction() {
        // Создаём аккаунты (если они ещё не существуют)
        Account a = createAccount("A", 1000);
        Account b = createAccount("B", 1000);

        // Выполняем перевод
        service.transfer(a, b, 100);

        // Теперь можно безопасно обращаться к данным, 
        // так как сессия всё ещё открыта благодаря @Transactional
        assertEquals(900, accounts.balance(a));
    }

    // Вспомогательный метод для создания аккаунтов
    private Account createAccount(String name, int balance) {
        Account account = new Account();
        account.setName(name);
        account.setBalance(balance);
        return accounts.save(account);
    }
}
